import React from 'react';

import { getHikingDataAsync } from '@apps/Hiking/@services/hiking.service';
import { IHikingData } from '@apps/Hiking/@types/hiking.types';
import HikingEditTimezones from '@apps/Hiking/edit/HikingEditTimezones';
import PageLoader from '@components/PageLoader';
import { err } from '@helpers/notificationHelper';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohContainer from '@ui-kit/layout/Container';

interface IHikingTimezonesProps {
  id_hiking: number;
}

const HikingTimezones: React.FC<IHikingTimezonesProps> = ({ id_hiking }) => {
  const [isLoading, setIsLoading] = React.useState(true);

  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const hd = await getHikingDataAsync(id_hiking);
        setHikingData(hd);
      } finally {
        setIsLoading(false);
      }
    };

    init().catch(err);
  }, [id_hiking]);

  if (isLoading || hikingData == null) {
    return <PageLoader />;
  }

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/timezones`, text: 'Часовые пояса', active: true },
        ]}
      />
      <HikingEditTimezones
        hikingData={hikingData}
        onChange={(up) => {
          setHikingData({
            ...hikingData,
            timezones: up,
          });
        }}
      />
    </PohContainer>
  );
};

export default HikingTimezones;
