/* eslint-disable @typescript-eslint/ban-ts-comment */
import React, { FormEvent } from 'react';

import Trash from '@pohodnik/icons/svg/UI/Trash';

import { getInputDate, getSQLDate } from '@helpers/dateHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohSelect from '@ui-kit/Select';

import {
  addHikingTimezone,
  deleteHikingTimezone,
  updateHikingTimezone,
} from '../../@services/hikingTimezones.service';
import {
  IHikingTimezoneCreateDTO,
  IHikingTimezoneUpdateDTO,
} from '../../@types/hiking.backendTypes';
import { IHikingTimezone } from '../../@types/hiking.baseTypes';

interface ITimezoneEditModalProps {
  id_hiking: number;
  onSave: (newTimezone: IHikingTimezone | null) => void;
  onCancel: () => void;
  data: IHikingTimezone;
}

const TimezoneEditModal: React.FC<ITimezoneEditModalProps> = ({ data, id_hiking, onSave }) => {
  const [isLoading, setIsLoading] = React.useState(false);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    const el = e.target as HTMLFormElement;

    // @ts-ignore
    const timezone = el.elements.timezone.value;
    // @ts-ignore
    const date_in = getSQLDate(new Date(el.elements.date_in.value));
    // @ts-ignore
    const date_out = getSQLDate(new Date(el.elements.date_out.value));
    // @ts-ignore
    const comment = el.elements.comment.value;

    if (!data.id) {
      const dataForAdd: IHikingTimezoneCreateDTO = {
        id_hiking: id_hiking.toString(),
        timezone,
        date_in,
        date_out,
        comment,
      };
      const newId = await addHikingTimezone(dataForAdd);
      const newTimezone: IHikingTimezone = {
        ...data,
        timezone,
        comment,
        date_in: new Date(date_in),
        date_out: new Date(date_out),
        id: newId,
      };
      onSave(newTimezone);
    } else {
      const dataForUpdate: IHikingTimezoneUpdateDTO = {
        id: data.id.toString(),
        id_hiking: id_hiking.toString(),
        timezone,
        date_in,
        date_out,
        comment,
      };
      await updateHikingTimezone(dataForUpdate);
      const newTimezone: IHikingTimezone = {
        ...data,
        timezone,
        comment,
        date_in: new Date(date_in),
        date_out: new Date(date_out),
      };
      onSave(newTimezone);
    }

    setIsLoading(false);
  };

  const handleDelete = async () => {
    setIsLoading(true);
    await deleteHikingTimezone(id_hiking, data.id);
    setIsLoading(false);
    onSave(null);
  };

  //@ts-ignore
  const allZones = Intl.supportedValuesOf('timeZone');
  return (
    <form onSubmit={handleSubmit}>
      <PohSelect
        options={allZones.map((s: string) => ({ value: s, label: s }))}
        required
        defaultValue={data?.timezone ?? Intl.DateTimeFormat().resolvedOptions().timeZone}
        name="timezone"
        label="Часовой пояс"
        disabled={isLoading}
      />
      <PohRow>
        <PohCol sm={6}>
          <PohInput
            required
            type={InputTypes.datetimeLocal}
            defaultValue={data?.date_in ? getInputDate(data.date_in) : ''}
            className="w-100"
            name="date_in"
            label="С какого времени"
            disabled={isLoading}
          />
        </PohCol>
        <PohCol sm={6}>
          <PohInput
            required
            type={InputTypes.datetimeLocal}
            defaultValue={data?.date_out ? getInputDate(data.date_out) : ''}
            className="w-100"
            name="date_out"
            label="По какое время"
            disabled={isLoading}
          />
        </PohCol>
      </PohRow>
      <PohInput
        type={InputTypes.textarea}
        defaultValue={data?.comment ?? ''}
        name="comment"
        label="Коммент"
        disabled={isLoading}
      />
      <footer className="d-flex pt-3">
        {data.id > 0 && (
          <PohButton
            onClick={handleDelete}
            disabled={isLoading}
            variant={ButtonVariant.Light}
            className="flex-shrink-0"
            title="удалить"
          >
            <Trash />
          </PohButton>
        )}

        <PohButton
          type="submit"
          className="ms-auto"
          disabled={isLoading}
          variant={ButtonVariant.Primary}
        >
          {data.id > 0 ? 'Сохранить' : 'Добавить'}
        </PohButton>
      </footer>
    </form>
  );
};

export default TimezoneEditModal;
