import React from 'react';

import clsx from 'clsx';

import { getHikingAccessGroupAsync } from '@apps/Hiking/@services/hikingRules.service';
import { HikingAccessGroup } from '@apps/Hiking/@types/hiking.rules';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import CurrentTimeInTimezone from './CurentTimeInTimezone';
import { editTimezoneAsync } from './timezonesModal.helper';
import { AuthContext } from '../../../../contexts/AuthContext';
import { IHikingTimezone } from '../../@types/hiking.baseTypes';
import { IHikingData } from '../../@types/hiking.types';

interface IHikingEditTimezonesProps {
  hikingData: IHikingData;
  onChange: (updatedTimezones: IHikingTimezone[]) => void;
}

const HikingEditTimezones: React.FC<IHikingEditTimezonesProps> = ({ hikingData, onChange }) => {
  const [canEdit, setCanEdit] = React.useState(false);
  const context = React.useContext(AuthContext);

  React.useEffect(() => {
    const start = async () => {
      const accessGroup = await getHikingAccessGroupAsync(hikingData.id);
      setCanEdit(
        [HikingAccessGroup.Full, HikingAccessGroup.All, HikingAccessGroup.Boss].includes(
          accessGroup,
        ),
      );
    };

    start();
  }, [hikingData.id]);

  const handleAdd = async () => {
    if (!context.user) return;
    if (!canEdit) return;
    const newItem = await editTimezoneAsync(
      {
        id: 0,
        date_in: new Date(),
        date_out: new Date(),
        comment: '',
        timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
        updated: null,
        created: {
          id: +context.user.id,
          name: context.user.name,
          date: new Date(),
        },
      },
      hikingData.id,
    );

    if (!newItem) return;

    onChange([...hikingData.timezones, newItem]);
  };

  return (
    <section className="p-3">
      <h5 className="mb-3">
        <PohButton
          variant={ButtonVariant.Success}
          className="float-end"
          size={ButtonSize.Small}
          onClick={handleAdd}
          disabled={!canEdit}
        >
          Добавить
        </PohButton>
        Часовые пояса
      </h5>
      <p className="text-muted">
        Если поход проходит в разных часовых поясах или в часовом поясе отличающемся от вашего (
        {Intl.DateTimeFormat().resolvedOptions().timeZone}). Можно добавить любое количество часовых
        поясов с указанием диапазона времени нахождения в них. Время во всех интерфейсах указывается{' '}
        <b>местное</b>, пометка часового пояса никак не меняет время. Отображение информации о
        часовом поясе поможет не забыть про разницу с привычным временем.
      </p>
      <PohList
        data={hikingData.timezones.map((tz) => {
          return {
            key: tz.id,
            className: ' flex-column align-items-start',
            content: (
              <PohRow className=" align-items-center">
                <PohCol sm={3}>
                  <small>
                    {[
                      tz.date_in.toLocaleString(navigator.language, {
                        dateStyle: 'short',
                        timeStyle: 'short',
                      }),
                      tz.date_out.toLocaleString(navigator.language, {
                        dateStyle: 'short',
                        timeStyle: 'short',
                      }),
                    ].join(' — ')}
                  </small>
                </PohCol>

                <PohCol sm={2}>
                  <strong
                    className={clsx(
                      Intl.DateTimeFormat().resolvedOptions().timeZone === tz.timezone
                        ? 'text-success'
                        : 'text-danger',
                    )}
                  >
                    {tz.timezone}
                  </strong>
                </PohCol>
                <PohCol sm={3}>
                  <small className="text-muted" title="Сейчас там">
                    <CurrentTimeInTimezone className="text-muted" timezone={tz.timezone} />
                  </small>
                </PohCol>
                <PohCol sm={4} className="text-md-end">
                  <em>{tz.comment}</em>
                </PohCol>
              </PohRow>
            ),
            action: canEdit,
            onClick: async () => {
              if (!context.user) return;
              if (!canEdit) return;
              const updatedItem = await editTimezoneAsync(
                {
                  ...tz,
                  updated: {
                    id: +context.user.id,
                    name: context.user.name,
                    date: new Date(),
                  },
                },
                hikingData.id,
              );
              updatedItem &&
                onChange(
                  hikingData.timezones.map((t) => (t.id === updatedItem.id ? updatedItem : t)),
                );
              updatedItem == null && onChange(hikingData.timezones.filter((t) => t.id !== tz.id));
            },
          };
        })}
      />
    </section>
  );
};

export default HikingEditTimezones;
