import React from 'react';

import { showModal } from '@ui-kit/Modal';

import HikingEditTimezones from '.';
import TimezoneEditModal from './TimezoneEditModal';
import { IHikingTimezone } from '../../@types/hiking.baseTypes';
import { IHikingData } from '../../@types/hiking.types';

export const showHikingTimezonesEditor = (
  hikingData: IHikingData,
  onChange: (updatedTimezones: IHikingTimezone[]) => void,
) => {
  showModal({
    size: 'lg',
    children: <HikingEditTimezones hikingData={hikingData} onChange={onChange} />,
  });
};

export const editTimezoneAsync = (
  tz: IHikingTimezone,
  id_hiking: number,
): Promise<IHikingTimezone | null> => {
  return new Promise((resolve, reject) => {
    showModal({
      title: tz.id ? 'Редактирование часового пояса' : 'Добавление часового пояса',
      children: (clos: any) => (
        <TimezoneEditModal
          id_hiking={id_hiking}
          onCancel={reject}
          onSave={(r) => {
            resolve(r);
            clos();
          }}
          data={tz}
        />
      ),
      onclose: reject,
    });
  });
};
